# Connect to the database as postgres
sudo -u postgres psql -d shop

# List indexes with type and size (inside psql)
\di+

# B-tree without blocking writes, then check it is valid
CREATE INDEX CONCURRENTLY orders_customer_id_idx ON orders (customer_id);
SELECT indexrelid::regclass, indisvalid FROM pg_index WHERE indrelid = 'orders'::regclass;

# Multicolumn: equality column first, then the sort or range column
CREATE INDEX CONCURRENTLY orders_customer_created_idx ON orders (customer_id, created_at);

# Covering index for index-only scans
CREATE INDEX CONCURRENTLY orders_customer_created_incl_idx ON orders (customer_id, created_at) INCLUDE (amount);

# Partial index for a small, hot subset
CREATE INDEX CONCURRENTLY orders_pending_created_idx ON orders (created_at) WHERE status = 'pending';

# Expression index, then refresh statistics
CREATE INDEX CONCURRENTLY orders_lower_email_idx ON orders (lower(email));
ANALYZE orders;

# GIN for jsonb containment (@>, @?, @@ only)
CREATE INDEX CONCURRENTLY orders_attrs_path_idx ON orders USING gin (attrs jsonb_path_ops);

# GiST exclusion constraint (needs btree_gist for the = column)
CREATE EXTENSION btree_gist;
ALTER TABLE room_bookings ADD EXCLUDE USING gist (room_id WITH =, during WITH &&);

# BRIN for a huge, time-ordered column
CREATE INDEX CONCURRENTLY orders_created_brin_idx ON orders USING brin (created_at);
SELECT brin_summarize_new_values('orders_created_brin_idx');

# Find unused indexes and invalid indexes
SELECT relname, indexrelname, idx_scan, last_idx_scan FROM pg_stat_user_indexes ORDER BY idx_scan;
SELECT indexrelid::regclass FROM pg_index WHERE NOT indisvalid;

# Save the definition, then drop without blocking
SELECT pg_get_indexdef('orders_lower_email_idx'::regclass);
DROP INDEX CONCURRENTLY orders_lower_email_idx;

